import{G as l,b as i,c as e,ae as t}from"./chunks/framework.l_MR1ur9.js";const _=JSON.parse('{"title":"概述","description":"","frontmatter":{"title":"概述","date":"2024/04/17 13:25:20","author":"花木凋零成兰","tags":[],"categories":["工程实践","软件测试"]},"headers":[],"relativePath":"Engineering/软件测试/1.概述/1.概述.md","filePath":"Engineering/软件测试/1.概述/1.概述.md","lastUpdated":1791630580000}'),r={name:"Engineering/软件测试/1.概述/1.概述.md"};function o(n,a,h,d,s,u){return i(),e("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1713360320000"},[...a[0]||(a[0]=[t('<h1 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h1><h2 id="为什么需要软件测试-核心价值" tabindex="-1">为什么需要软件测试(核心价值)? <a class="header-anchor" href="#为什么需要软件测试-核心价值" aria-label="Permalink to &quot;为什么需要软件测试(核心价值)?&quot;">​</a></h2><ul><li>软件测试职位本来带来的价值; 确保产品的质量</li><li>软件测试人员比其他人做软件测试工作, 效率更高, 效果更好</li><li>软件测试是软件产品质量保证的重要措施之一</li></ul><h2 id="哪些人需要了解软件测试" tabindex="-1">哪些人需要了解软件测试? <a class="header-anchor" href="#哪些人需要了解软件测试" aria-label="Permalink to &quot;哪些人需要了解软件测试?&quot;">​</a></h2><ul><li>用户</li><li>项目经理</li><li><strong>程序员</strong></li><li>测试员</li></ul><h2 id="软件测试等级划分" tabindex="-1">软件测试等级划分 <a class="header-anchor" href="#软件测试等级划分" aria-label="Permalink to &quot;软件测试等级划分&quot;">​</a></h2><h3 id="第1级-初始阶段" tabindex="-1">第1级. 初始阶段 <a class="header-anchor" href="#第1级-初始阶段" aria-label="Permalink to &quot;第1级. 初始阶段&quot;">​</a></h3><ul><li>措施：测试是完全混乱无序的，测试等同于调试，编码完成后随意地测试和调试，目标是表明软件是奏效的。</li><li>优势：最省力气。</li><li>弊端：开发出的软件产品得不到任何质量的保证，存在很多缺陷，用户无法接受。</li></ul><h3 id="第2级-定义阶段" tabindex="-1">第2级. 定义阶段 <a class="header-anchor" href="#第2级-定义阶段" aria-label="Permalink to &quot;第2级. 定义阶段&quot;">​</a></h3><ul><li>措施：测试不同于调试。将测试定义为编码完成后的阶段和工作，所有测试都是基于执行的，而且强烈依赖于代码，只有当编码完成后才开始测试，目标是表明软件符合其技术规范。</li><li>优势：人们掌握了一定的测试技术和方法，取得了一定的效果。</li><li>弊端：在需求和设计中没有测试，从而导致大量缺陷扩散到代码中，开发出的软件产品仍然会存在较多缺陷，产品存在质量问题。</li></ul><h3 id="第3级-集成阶段" tabindex="-1">第3级. 集成阶段 <a class="header-anchor" href="#第3级-集成阶段" aria-label="Permalink to &quot;第3级. 集成阶段&quot;">​</a></h3><ul><li>措施：将测试集成到整个软件生存周期，开始考虑客户和用户的需求来建立测试目标，将测试看做专业化的活动，成立专门的测试组织，拥有基本的测试工具。</li><li>优势：基于技术的测试，效果更好。</li><li>弊端：在整个软件生存周期中没有建立正式的评审程序，没有开展评审活动，测试组疲于应付。</li></ul><h3 id="第4级-管理与测量" tabindex="-1">第4级. 管理与测量 <a class="header-anchor" href="#第4级-管理与测量" aria-label="Permalink to &quot;第4级. 管理与测量&quot;">​</a></h3><ul><li>措施：测试成为一个可以测量和量化的过程，开发过程引入评审机制，测试用例和测试过程被管理起来。</li><li>优势：基于规范的测试，拥有流程控制，出现质量管理活动。</li><li>弊端：只能被动地找缺陷，无法主动控制缺陷。</li></ul><h3 id="第5级-最佳化" tabindex="-1">第5级. 最佳化 <a class="header-anchor" href="#第5级-最佳化" aria-label="Permalink to &quot;第5级. 最佳化&quot;">​</a></h3><ul><li>措施：建立缺陷预防的思想，通过统计抽样等方式不断改进测试，自动工具完全支持测试用例的运行，开展各种与测试有关的度量活动。</li><li>优势：机制好转，不断改进测试，可以度量和优化产品质量。</li></ul>',16)])])}const b=l(r,[["render",o]]);export{_ as __pageData,b as default};
